from typing_extensions import TypedDict
from langgraph.graph import StateGraph, START, END


class State(TypedDict):
    value: int


def node_a(state: State) -> dict:
    return {"value": state["value"] + 1}


def routing_function(state: State) -> str:
    return "node_b" if state["value"] > 0 else "node_c"


def node_b(state: State) -> dict:
    return {"value": 0}


def node_c(state: State) -> dict:
    return {"value": -1}


builder = StateGraph(State)
builder.add_node("node_a", node_a)
builder.add_node("node_b", node_b)
builder.add_node("node_c", node_c)
builder.add_edge(START, "node_a")
builder.add_conditional_edges("node_a", routing_function)
builder.add_edge("node_b", END)
builder.add_edge("node_c", END)
graph = builder.compile()

from typing_extensions import TypedDict
from langgraph.graph import StateGraph, START, END
from langgraph.types import Send


class OverallState(TypedDict):
    subjects: list[str]
    jokes: list[str]


def plan(state: OverallState) -> dict:
    return {}


def continue_to_jokes(state: OverallState):
    return [Send("generate_joke", {"subject": s}) for s in state["subjects"]]


def generate_joke(state) -> dict:
    return {"jokes": ["a joke about " + state["subject"]]}


builder = StateGraph(OverallState)
builder.add_node("plan", plan)
builder.add_node("generate_joke", generate_joke)
builder.add_edge(START, "plan")
builder.add_conditional_edges("plan", continue_to_jokes)
builder.add_edge("generate_joke", END)
graph = builder.compile()
